const date=s=>new Intl.DateTimeFormat('ru',{day:'numeric',month:'short'}).format(new Date(s+'T12:00:00'));
const plural=(n,one,few,many)=>`${n} ${{one,few,many,other:many}[new Intl.PluralRules('ru').select(n)]}`;
