 const startUpload=async(file:File,metadata:Record<string,unknown>)=>{if(uploadTask?.state==='uploading')return;uploadSource.current={file,metadata};setUploadTask({state:'uploading',name:file.name,percent:0,size:file.size});try{const result=await uploadFile(file,{...metadata,workspaceId:authInfo.user?.workspaceId},percent=>setUploadTask(t=>({...t,percent})));receive(result);setUploadTask({state:'ready',name:file.name,percent:100,studyId:result.createdStudyId});if(result.createdStudyId)go('study/'+result.createdStudyId);notify('Файл сохранён. Статус расшифровки — на странице материала.')}catch(e){setUploadTask(t=>({...t,state:'error',error:e.message}));}};
