 useEffect(()=>{const h=()=>{if(location.hash==='#main'){main.current?.focus();return}setRoute(location.hash.slice(2)||'home');setMenuOpen(false);window.scrollTo(0,0);requestAnimationFrame(()=>main.current?.focus({preventScroll:true}))};window.addEventListener('hashchange',h);return()=>window.removeEventListener('hashchange',h)},[]);
