 useEffect(()=>{document.documentElement.dataset.theme=effectiveTheme;document.documentElement.style.colorScheme=effectiveTheme;const label=[...navs,...management].find(x=>x[0]===route.split('?')[0])?.[1]||state.studies.find(s=>route==='study/'+s.id)?.title||(route==='signup'?'Регистрация':route==='login'?'Вход':'Материал');document.title=label+' — Мнемонио'},[effectiveTheme,route,state.studies]);
 useEffect(()=>()=>{clearTimeout(timer.current);for(const f of files.current.values())URL.revokeObjectURL(f.url)},[]);
