 const ask=async q=>{if(!DEMO){if(typing||!q.trim())return;setTyping(true);setState(s=>({...s,messages:[...s.messages,{id:uid(),role:'user',text:q}]}));go('chat');try{const answer=await api('/api/chat',{question:q,modelId:state.modelId,scope});setState(s=>({...s,messages:[...s.messages,{id:uid(),role:'assistant',real:true,...answer}]}))}catch(e){setToast(e.message);setState(s=>({...s,messages:[...s.messages,{id:uid(),role:'assistant',real:true,answer:e.message,sources:[],model:'Подключение'}]}))}finally{setTyping(false)}return}if(typing||!q.trim())return;const model=state.models.find(m=>m.id===state.modelId&&m.enabled)||state.models.find(m=>m.enabled);if(!model){notify('Включите модель в настройках, чтобы задать вопрос.');return}update(s=>({messages:[...s.messages,{id:uid(),role:'user',text:q}]}));setTyping(true);go('chat');clearTimeout(timer.current);const sourceScope=scope;timer.current=setTimeout(()=>{const relevant=(sourceScope==='all'||sourceScope==='calendar')&&/цен|календар|хозя|провер|вывод|вопрос|невыяснен|измен|сохран/i.test(q);update(s=>({messages:[...s.messages,{id:uid(),role:'assistant',model:model.name,empty:!relevant,open:/открыт|вопрос|невыяснен/i.test(q)}]}));setTyping(false)},1200)};
 const theme=()=>{document.documentElement.classList.add('theme-changing');update({theme:effectiveTheme==='dark'?'light':'dark'});requestAnimationFrame(()=>requestAnimationFrame(()=>document.documentElement.classList.remove('theme-changing')))};
 const openPanel=p=>setPanel(p);const switchWorkspaceRef=useRef<((id:string)=>Promise<void>)|null>(null);
const context={startUpload,uploadTask,switchWorkspace:(id:string)=>switchWorkspaceRef.current?.(id),markSeen,state,update,receive,user:authInfo.user,real:!DEMO,reader,route,go,dialog,open,notify,selected,setSelected,scope,setScope,typing,ask,files,panel,setPanel,openPanel};
 const base=route.split('?')[0];
